        "supermemoryai/opencode-supermemory — package.json\n* Page: GitHub code file\n* URL: https://github.com/supermemoryai/opencode-supermemory/blob/main/package.json\n* Repository: supermemoryai/opencode-supermemory\n* Path: package.json\n* Ref: main\n* Lines: 49\n{\n\"name\": \"opencode-supermemory\",\n\"version\": \"2.0.13\",\n\"description\": \"OpenCode plugin that gives coding agents persistent memory using Supermemory\",\n\"type\": \"module\",\n\"main\": \"dist/index.js\",\n\"types\": \"dist/index.d.ts\",\n\"bin\": {\n\"opencode-supermemory\": \"./dist/cli.js\"\n},\n\"scripts\": {\n\"generate:version\": \"node scripts/sync-version.mjs\",\n\"build\": \"node scripts/sync-version.mjs && bun build ./src/index.ts --outdir ./dist --target node && bun build ./src/cli.ts --outfile ./dist/cli.js --target node && tsc --emitDeclarationOnly\",\n\"dev\": \"tsc --watch\",\n\"typecheck\": \"node scripts/sync-version.mjs && tsc --noEmit\",\n\"test\": \"node scripts/sync-version.mjs && bun test\"\n},\n\"keywords\": [\n\"opencode\",\n\"plugin\",\n\"supermemory\",\n\"memory\",\n\"ai\",\n\"coding-agent\"\n],\n\"author\": \"Supermemory\",\n\"license\": \"MIT\",\n\"repository\": {\n\"type\": \"git\",\n\"url\": \"https://github.com/supermemoryai/opencode-supermemory\"\n},\n\"devDependencies\": {\n\"@opencode-ai/plugin\": \"^1.0.162\",\n\"@types/bun\": \"latest\",\n\"supermemory\": \"^4.0.0\",\n\"typescript\": \"^5.7.3\"\n},\n\"opencode\": {\n\"type\": \"plugin\",\n\"hooks\": [\n\"chat.message\",\n\"permission.ask\",\n\"event\"\n]\n},\n\"files\": [\n\"dist\"\n]\n}"
