{"type":"tool","tool":"write","callID":"call_dde576df89ef41c88d9b4cc1","state":{"status":"completed","input":{"filePath":"/tmp/opencode-session-picker/src/cli.ts","content":"#!/usr/bin/env node

import inquirer from 'inquirer';
import * as fs from 'fs';
import * as path from 'path';
import { OpenCodeDB } from './db';
import { SessionPreview, ExportOptions, BackupOptions } from './types';

const db = new OpenCodeDB();

function formatDate(date: Date): string {
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function formatSession(session: SessionPreview, index: number): string {
  const preview = session.preview ? ` - ${session.preview.substring(0, 50)}...` : '';
  return `[${index + 1}] ${session.title} (${session.messageCount} messages, ${formatDate(session.updatedAt)})${preview}`;
}

async function listSessions(): Promise<void> {
  if (!db.connect()) {
    console.error('无法连接到 OpenCode 数据库');
    process.exit(1);
  }

  try {
    const sessions = db.getSessionsWithPreview(20);

    if (sessions.length === 0) {
      console.log('没有找到会话');
      return;
    }

    console.log('\n=== OpenCode 会话列表 ===\n');
    sessions.forEach((session, index) => {
      console.log(formatSession(session, index));
    });
    console.log('\n使用 "opencode-session-picker select" 交互式选择会话');
  } finally {
    db.disconnect();
  }
}

async function selectSession(): Promise<void> {
  if (!db.connect()) {
    console.error('无法连接到 OpenCode 数据库');
    process.exit(1);
  }

  try {
    const sessions = db.getSessionsWithPreview(50);

    if (sessions.length === 0) {
      console.log('没有找到会话');
      return;
    }

    const { action } = await inquirer.prompt([
      {
        type: 'list',
        name: 'action',
        message: '选择操作:',
        choices: [
          { name: '选择会话继续', value: 'select' },
          { name: '搜索会话', value: 'search' },
          { name: '导出会话', value: 'export' },
          { name: '退出', value: 'exit' },
        ],
      },
    ]);

    if (action === 'exit') {
      return;
    }

    if (action === 'search') {
      const { query } = await inquirer.prompt([
        {
          type: 'input',
          name: 'query',
          message: '输入搜索关键词:',
        },
      ]);

      const results = db.searchSessions(query);
      if (results.length === 0) {
        console.log('没有找到匹配的会话');
        return;
      }

      const { selectedId } = await inquirer.prompt([
        {
          type: 'list',
          name: 'selectedId',
          message: '选择会话:',
          choices: results.map(s => ({
            name: `${s.title || 'Untitled'} (${formatDate(new Date(s.updated_at * 1000))})`,
            value: s.id,
          })),
        },
      ]);

      await launchSession(selectedId);
      return;
    }

    if (action === 'export') {
      const { selectedId } = await inquirer.prompt([
        {
          type: 'list',
          name: 'selectedId',
          message: '选择要导出的会话:',
          choices: sessions.map(s => ({
            name: `${s.title} (${formatDate(s.updatedAt)})`,
            value: s.id,
          })),
        },
      ]);

      await exportSession(selectedId);
      return;
    }

    const { selectedId } = await inquirer.prompt([
      {
        type: 'list',
        name: 'selectedId',
        message: '选择要继续的会话:',
        choices: sessions.map(s => ({
          name: `${s.title} (${s.messageCount} messages, ${formatDate(s.updatedAt)})`,
          value: s.id,
        })),
      },
    ]);

    const { confirm } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'confirm',
        message: `确定要继续会话 "${sessions.find(s => s.id === selectedId)?.title}" 吗?`,
        default: true,
      },
    ]);

    if (confirm) {
      await launchSession(selectedId);
    }
  } finally {
    db.disconnect();
  }
}

async function launchSession(sessionId: string): Promise<void> {
  const session = db.getSession(sessionId);
  if (!session) {
    console.error('会话不存在');
    return;
  }

  console.log(`\n启动 OpenCode 并继续会话: ${session.title || sessionId}`);
  console.log(`命令: opencode run --session ${sessionId}\n`);

  const { execSync } = await import('child_process');
  try {
    execSync(`opencode run --session ${sessionId}`, { stdio: 'inherit' });
  } catch (error) {
    console.error('启动 OpenCode 失败，请确保已安装 OpenCode');
  }
}

async function resumeSession(sessionId: string): Promise<void> {
  if (!db.connect()) {
    console.error('无法连接到 OpenCode 数据库');
    process.exit(1);
  }

  try {
    const session = db.getSession(sessionId);
    if (!session) {
      console.error(`会话 ${sessionId} 不存在`);
      process.exit(1);
    }

    console.log(`继续会话: ${session.title || sessionId}`);
    await launchSession(sessionId);
  } finally {
    db.disconnect();
  }
}

async function exportSession(sessionId: string): Promise<void> {
  if (!db.connect()) {
    console.error('无法连接到 OpenCode 数据库');
    process.exit(1);
  }

  try {
    const { format } = await inquirer.prompt([
      {
        type: 'list',
        name: 'format',
        message: '选择导出格式:',
        choices: [
          { name: 'JSON (完整数据)', value: 'json' },
          { name: 'Markdown (可读格式)', value: 'markdown' },
          { name: '纯文本', value: 'text' },
        ],
      },
    ]);

    const exportData = db.exportSession(sessionId);
    if (!exportData) {
      console.error('导出会话失败');
      return;
    }

    const session = db.getSession(sessionId);
    const filename = `session-${sessionId.substring(0, 8)}-${Date.now()}.${format === 'json' ? 'json' : format === 'markdown' ? 'md' : 'txt'}`;
    const outputPath = path.join(process.cwd(), filename);

    let content: string;

    if (format === 'json') {
      content = JSON.stringify(exportData, null, 2);
    } else if (format === 'markdown') {
      content = formatAsMarkdown(exportData);
    } else {
      content = formatAsText(exportData);
    }

    fs.writeFileSync(outputPath, content, 'utf-8');
    console.log(`\n会话已导出到: ${outputPath}`);
  } finally {
    db.disconnect();
  }
}

function formatAsMarkdown(data: any): string {
  const { session, messages } = data;
  let md = `# ${session.title || 'Untitled Session'}\n\n`;
  md += `- **ID**: ${session.id}\n`;
  md += `- **创建时间**: ${new Date(session.created_at * 1000).toLocaleString()}\n`;
  md += `- **更新时间**: ${new Date(session.updated_at * 1000).toLocaleString()}\n`;
  md += `- **消息数**: ${session.message_count}\n\n`;
  md += `---\n\n`;

  for (const msg of messages) {
    const role = msg.role === 'user' ? '👤 User' : '🤖 Assistant';
    md += `## ${role}\n\n`;

    for (const part of msg.parts) {
      if (part.type === 'text') {
        const textData = JSON.parse(part.data);
        md += `${textData.text}\n\n`;
      } else if (part.type === 'tool-call') {
        const toolData = JSON.parse(part.data);
        md += `**Tool Call**: ${toolData.name}\n`;
        md += `\`\`\`json\n${JSON.stringify(toolData.arguments, null, 2)}\n\`\`\`\n\n`;
      }
    }
  }

  return md;
}

function formatAsText(data: any): string {
  const { session, messages } = data;
  let text = `Session: ${session.title || 'Untitled'}\n`;
  text += `ID: ${session.id}\n`;
  text += `Created: ${new Date(session.created_at * 1000).toLocaleString()}\n`;
  text += `Messages: ${session.message_count}\n`;
  text += `${'='.repeat(50)}\n\n`;

  for (const msg of messages) {
    const role = msg.role === 'user' ? 'USER' : 'ASSISTANT';
    text += `[${role}]\n`;

    for (const part of msg.parts) {
      if (part.type === 'text') {
        const textData = JSON.parse(part.data);
        text += `${textData.text}\n`;
      }
    }
    text += '\n';
  }

  return text;
}

async function backupSessions(options: BackupOptions): Promise<void> {
  if (!db.connect()) {
    console.error('无法连接到 OpenCode 数据库');
    process.exit(1);
  }

  try {
    const backupDir = path.join(process.cwd(), 'opencode-backups');
    if (!fs.existsSync(backupDir)) {
      fs.mkdirSync(backupDir, { recursive: true });
    }

    let sessions;
    if (options.includeAll) {
      sessions = db.listSessions();
    } else if (options.sessionIds && options.sessionIds.length > 0) {
      sessions = options.sessionIds.map(id => db.getSession(id)).filter(Boolean);
    } else {
      console.log('未指定要备份的会话');
      return;
    }

    const backupFile = path.join(backupDir, `backup-${Date.now()}.json`);
    const backupData = {
      createdAt: new Date().toISOString(),
      sessions: sessions.map(s => db.exportSession(s!.id)).filter(Boolean),
    };

    fs.writeFileSync(backupFile, JSON.stringify(backupData, null, 2), 'utf-8');
    console.log(`\n备份完成: ${backupFile}`);
    console.log(`包含 ${backupData.sessions.length} 个会话`);
  } finally {
    db.disconnect();
  }
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const command = args[0];

  switch (command) {
    case 'list':
      await listSessions();
      break;

    case 'select':
    case undefined:
      await selectSession();
      break;

    case 'resume':
      if (!args[1]) {
        console.error('请提供会话 ID: opencode-session-picker resume <session-id>');
        process.exit(1);
      }
      await resumeSession(args[1]);
      break;

    case 'export':
      if (!args[1]) {
        console.error('请提供会话 ID: opencode-session-picker export <session-id>');
        process.exit(1);
      }
      if (!db.connect()) {
        console.error('无法连接到 OpenCode 数据库');
        process.exit(1);
      }
      await exportSession(args[1]);
      db.disconnect();
      break;

    case 'backup':
      await backupSessions({
        includeAll: args.includes('--all'),
        sessionIds: args.slice(1).filter(a => !a.startsWith('--')),
        compress: args.includes('--compress'),
      });
      break;

    case 'help':
    case '--help':
    case '-h':
      console.log(`
OpenCode Session Picker - 会话选择和管理工具

用法:
  opencode-session-picker [command] [options]

命令:
  list                    列出最近的会话
  select                  交互式选择会话
  resume <session-id>     继续指定会话
  export <session-id>     导出会话
  backup [options]        备份会话
  help                    显示帮助信息

选项:
  --all                   备份所有会话
  --compress              压缩备份文件

示例:
  opencode-session-picker list
  opencode-session-picker select
  opencode-session-picker resume abc123
  opencode-session-picker export abc123
  opencode-session-picker backup --all
      `);
      break;

    default:
      console.error(`未知命令: ${command}`);
      console.log('使用 "opencode-session-picker help" 查看帮助');
      process.exit(1);
  }
}

main().catch(error => {
  console.error('错误:', error);
  process.exit(1);
});
