import { OpenCodeDB } from './db';
import { PluginOptions, ExportOptions, BackupOptions } from './types';

export const SessionPickerPlugin: Plugin = async (ctx) => {
  const options: PluginOptions = ctx.options || {};
  const db = new OpenCodeDB();

  const formatDate = (timestamp: number): string => {
    return new Date(timestamp * 1000).toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return {
    tool: {
      session_list: tool({
        description: "列出所有会话，支持搜索和分页",
        args: {
          limit: tool.schema.number().optional().describe("返回的会话数量，默认20"),
          search: tool.schema.string().optional().describe("搜索关键词"),
        },
        async execute(args, context) {
          const limit = args.limit || options.maxSessions || 20;
          const search = args.search;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            const sessions = search 
              ? db.searchSessions(search)
              : db.listSessions(limit);

            if (sessions.length === 0) {
              return "没有找到会话";
            }

            const formatted = sessions.slice(0, limit).map((s, i) => {
              const title = s.title || 'Untitled';
              const date = formatDate(s.updated_at);
              return `[${i + 1}] ${title} (${s.message_count} 条消息, ${date}) ID: ${s.id}`;
            });

            return `找到 ${sessions.length} 个会话:\n\n${formatted.join('\n')}`;
          } finally {
            db.disconnect();
          }
        },
      }),

      session_search: tool({
        description: "搜索会话内容，支持标题和消息内容搜索",
        args: {
          query: tool.schema.string().describe("搜索关键词"),
          session_id: tool.schema.string().optional().describe("限定在特定会话中搜索"),
        },
        async execute(args) {
          const { query, session_id } = args;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            if (session_id) {
              const messages = db.getSessionMessages(session_id);
              const matchingMessages = messages.filter(m => {
                const parts = db.getMessageParts(m.id);
                return parts.some(p => p.data.includes(query));
              });

              if (matchingMessages.length === 0) {
                return `在会话 ${session_id} 中没有找到匹配 "${query}" 的内容`;
              }

              return `在会话中找到 ${matchingMessages.length} 条匹配消息`;
            }

            const sessions = db.searchSessions(query);
            if (sessions.length === 0) {
              return `没有找到包含 "${query}" 的会话`;
            }

            const formatted = sessions.map((s, i) => {
              const title = s.title || 'Untitled';
              const date = formatDate(s.updated_at);
              return `[${i + 1}] ${title} (${date}) ID: ${s.id}`;
            });

            return `找到 ${sessions.length} 个相关会话:\n\n${formatted.join('\n')}`;
          } finally {
            db.disconnect();
          }
        },
      }),

      session_switch: tool({
        description: "切换到指定会话",
        args: {
          session_id: tool.schema.string().describe("目标会话 ID"),
          fork: tool.schema.boolean().optional().describe("是否创建分支，默认 false"),
        },
        async execute(args, context) {
          const { session_id, fork } = args;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            const session = db.getSession(session_id);
            if (!session) {
              return `会话 ${session_id} 不存在`;
            }

            const title = session.title || 'Untitled';
            const command = fork 
              ? `opencode run --session ${session_id} --fork`
              : `opencode run --session ${session_id}`;

            return `已切换到会话 "${title}"\n\n请在终端中运行以下命令继续会话:\n${command}`;
          } finally {
            db.disconnect();
          }
        },
      }),

      session_info: tool({
        description: "获取会话详细信息",
        args: {
          session_id: tool.schema.string().describe("会话 ID"),
        },
        async execute(args) {
          const { session_id } = args;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            const session = db.getSession(session_id);
            if (!session) {
              return `会话 ${session_id} 不存在`;
            }

            const messages = db.getSessionMessages(session_id);
            const lastMessage = messages[messages.length - 1];
            let lastMessagePreview = '';

            if (lastMessage) {
              const parts = db.getMessageParts(lastMessage.id);
              const textParts = parts.filter(p => p.type === 'text');
              if (textParts.length > 0) {
                const data = JSON.parse(textParts[0].data);
                lastMessagePreview = (data.text || '').substring(0, 200);
              }
            }

            return [
              `会话详情:`,
              `- ID: ${session.id}`,
              `- 标题: ${session.title || 'Untitled'}`,
              `- 消息数: ${session.message_count}`,
              `- Token 使用: ${session.prompt_tokens} (输入) / ${session.completion_tokens} (输出)`,
              `- 创建时间: ${formatDate(session.created_at)}`,
              `- 更新时间: ${formatDate(session.updated_at)}`,
              lastMessagePreview ? `\n最后消息预览:\n${lastMessagePreview}...` : '',
            ].filter(Boolean).join('\n');
          } finally {
            db.disconnect();
          }
        },
      }),

      session_export: tool({
        description: "导出会话为 JSON 格式",
        args: {
          session_id: tool.schema.string().describe("会话 ID"),
          output_path: tool.schema.string().optional().describe("输出文件路径，默认当前目录"),
