        async execute(args) {
          const { session_id, output_path } = args;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            const exportData = db.exportSession(session_id);
            if (!exportData) {
              return `导出会话 ${session_id} 失败`;
            }

            const filename = `session-${session_id.substring(0, 8)}-${Date.now()}.json`;
            const outputPath = output_path 
              ? path.join(output_path, filename)
              : path.join(process.cwd(), filename);

            fs.writeFileSync(outputPath, JSON.stringify(exportData, null, 2), 'utf-8');
            return `会话已导出到: ${outputPath}`;
          } finally {
            db.disconnect();
          }
        },
      }),

      session_backup: tool({
        description: "备份会话",
        args: {
          session_ids: tool.schema.string().optional().describe("要备份的会话 ID，多个用逗号分隔"),
          all: tool.schema.boolean().optional().describe("备份所有会话，默认 false"),
          output_path: tool.schema.string().optional().describe("备份输出路径"),
        },
        async execute(args) {
          const { session_ids, all, output_path } = args;

          if (!db.connect()) {
            return "无法连接到 OpenCode 数据库";
          }

          try {
            const backupDir = output_path || path.join(process.cwd(), 'opencode-backups');
            if (!fs.existsSync(backupDir)) {
              fs.mkdirSync(backupDir, { recursive: true });
            }

            let sessions;
            if (all) {
              sessions = db.listSessions();
            } else if (session_ids) {
              const ids = session_ids.split(',').map(id => id.trim());
              sessions = ids.map(id => db.getSession(id)).filter(Boolean);
            } else {
              return "请指定要备份的会话 ID 或使用 --all 参数";
            }

            if (sessions.length === 0) {
              return "没有找到要备份的会话";
            }

            const backupFile = path.join(backupDir, `backup-${Date.now()}.json`);
            const backupData = {
              createdAt: new Date().toISOString(),
              sessions: sessions.map(s => db.exportSession(s!.id)).filter(Boolean),
            };

            fs.writeFileSync(backupFile, JSON.stringify(backupData, null, 2), 'utf-8');
            return `备份完成: ${backupFile}\n包含 ${backupData.sessions.length} 个会话`;
          } finally {
            db.disconnect();
          }
        },
      }),
    },

