      // 监听会话事件（可扩展）
      if (event.type === 'session.created') {
        ctx.client.app.log({
          body: {
            service: 'session-picker',
            level: 'info',
            message: `新会话创建: ${event.properties.id}`,
          },
        });
      }
    },
  };
};

export default SessionPickerPlugin;
