1: import { tool } from "@opencode-ai/plugin";
2: import * as fs from 'fs';
3: import * as path from 'path';
4: import { OpenCodeDB } from './db.js';
5: import { PluginOptions, ExportOptions, BackupOptions } from './types.js';
6: import { i18n } from './i18n.js';
7: 
8: export const SessionPickerPlugin = async (ctx: any) => {
9:   const options: PluginOptions = ctx.options || {};
10:   const db = new OpenCodeDB();
11: 
12:   const formatDate = (timestamp: number): string => {
13:     return new Date(timestamp * 1000).toLocaleString(i18n.getLanguage() === 'zh' ? 'zh-CN' : 'en-US', {
14:       year: 'numeric',
15:       month: '2-digit',
16:       day: '2-digit',
17:       hour: '2-digit',
18:       minute: '2-digit',
19:     });
20:   };
21: 
22:   return {
23:     tool: {
24:       session_list: tool({
25:         description: i18n.t('tools.sessionListDesc'),
26:         args: {
27:           limit: tool.schema.number().optional().describe(i18n.t('tools.limitParam')),
28:           search: tool.schema.string().optional().describe(i18n.t('tools.searchParam')),
29:         },
30:         async execute(args: any, context: any) {
31:           const limit = args.limit || options.maxSessions || 20;
32:           const search = args.search;
33: 
34:           if (!db.connect()) {
35:             return i18n.t('errors.databaseConnectionFailed');
36:           }
37: 
38:           try {
39:             const sessions = search 
40:               ? db.searchSessions(search)
41:               : db.listSessions(limit);
42: 
43:             if (sessions.length === 0) {
44:               return i18n.t('prompts.noSessionsFound');
45:             }
46: 
47:             const formatted = sessions.slice(0, limit).map((s: any, i: number) => {
48:               const title = s.title || i18n.t('session.untitled');
49:               const date = formatDate(s.time_updated);
50:               return `[${i + 1}] ${title} (${s.message_count || 0} ${i18n.t('session.messageCount').toLowerCase()}, ${date}) ID: ${s.id}`;
51:             });
52: 
53:             return i18n.t('results.foundSessions', { count: String(sessions.length) }) + ':\n\n' + formatted.join('\n');
54:           } finally {
55:             db.disconnect();
56:           }
57:         },
58:       }),
59: 
60:       session_search: tool({
61:         description: i18n.t('tools.sessionSearchDesc'),
62:         args: {
63:           query: tool.schema.string().describe(i18n.t('tools.searchParam')),
64:           session_id: tool.schema.string().optional().describe(i18n.t('tools.sessionIdParam')),
65:         },
66:         async execute(args: any) {
67:           const { query, session_id } = args;
68: 
69:           if (!db.connect()) {
70:             return i18n.t('errors.databaseConnectionFailed');
71:           }
72: 
73:           try {
74:             if (session_id) {
75:               const messages = db.getSessionMessages(session_id);
76:               const matchingMessages = messages.filter((m: any) => {
77:                 const parts = db.getMessageParts(m.id);
78:                 return parts.some((p: any) => p.data.includes(query));
79:               });
80: 
81:               if (matchingMessages.length === 0) {
82:                 return i18n.getLanguage() === 'zh' 
83:                   ? `在会话 ${session_id} 中没有找到匹配 "${query}" 的内容`
84:                   : `No matching content found in session ${session_id} for "${query}"`;
85:               }
86: 
87:               return i18n.getLanguage() === 'zh'
88:                 ? `在会话中找到 ${matchingMessages.length} 条匹配消息`
89:                 : `Found ${matchingMessages.length} matching messages in session`;
90:             }
91: 
92:             const sessions = db.searchSessions(query);
93:             if (sessions.length === 0) {
94:               return i18n.getLanguage() === 'zh'
95:                 ? `没有找到包含 "${query}" 的会话`
96:                 : `No sessions found containing "${query}"`;
97:             }
98: 
99:             const formatted = sessions.map((s: any, i: number) => {
100:               const title = s.title || i18n.t('session.untitled');
101:               const date = formatDate(s.time_updated);
102:               return `[${i + 1}] ${title} (${date}) ID: ${s.id}`;
103:             });
104: 
105:             return i18n.t('results.foundSessions', { count: String(sessions.length) }) + ':\n\n' + formatted.join('\n');
106:           } finally {
107:             db.disconnect();
108:           }
109:         },
110:       }),
111: 
112:       session_switch: tool({
113:         description: i18n.t('tools.sessionSwitchDesc'),
114:         args: {
115:           session_id: tool.schema.string().describe(i18n.t('tools.sessionIdParam')),
116:           fork: tool.schema.boolean().optional().describe(i18n.t('tools.forkParam')),
117:         },
118:         async execute(args: any, context: any) {
119:           const { session_id, fork } = args;
120: 
121:           if (!db.connect()) {
122:             return i18n.t('errors.databaseConnectionFailed');
123:           }
124: 
125:           try {
126:             const session = db.getSession(session_id);
127:             if (!session) {
128:               return i18n.t('errors.sessionNotExist', { id: session_id });
129:             }
130: 
131:             const title = session.title || i18n.t('session.untitled');
132:             const command = fork 
133:               ? `opencode run --session ${session_id} --fork`
134:               : `opencode run --session ${session_id}`;
135: 
