        } catch {
          text += `${part.data}\n`;
        }
      }
    }
    text += '\n';
  }

  return text;
}

async function backupSessions(options: BackupOptions): Promise<void> {
  if (!db.connect()) {
    console.error(i18n.t('errors.databaseConnectionFailed'));
    process.exit(1);
  }

  try {
    const backupDir = path.join(process.cwd(), 'opencode-backups');
