264: function formatAsMarkdown(data: any): string {
265:   const { session, messages } = data;
266:   let md = `# ${session.title || i18n.t('session.untitled')}\n\n`;
267:   md += `- **${i18n.t('session.id')}**: ${session.id}\n`;
268:   md += `- **${i18n.t('session.createdAt')}**: ${new Date(session.time_created * 1000).toLocaleString()}\n`;
269:   md += `- **${i18n.t('session.updatedAt')}**: ${new Date(session.time_updated * 1000).toLocaleString()}\n`;
270:   md += `- **${i18n.t('session.messageCount')}**: ${session.message_count || messages.length}\n\n`;
271:   md += `---\n\n`;
272: 
273:   for (const msg of messages) {
274:     const role = msg.data?.role === 'user' ? 'User' : 'Assistant';
275:     md += `## ${role}\n\n`;
276: 
277:     for (const part of msg.parts) {
278:       if (part.type === 'text') {
279:         try {
280:           const textData = JSON.parse(part.data);
281:           md += `${textData.text}\n\n`;
282:         } catch {
283:           md += `${part.data}\n\n`;
284:         }
285:       } else if (part.type === 'tool-call') {
286:         try {
287:           const toolData = JSON.parse(part.data);
288:           md += `**Tool Call**: ${toolData.name}\n`;
289:           md += `\`\`\`json\n${JSON.stringify(toolData.arguments, null, 2)}\n\`\`\`\n\n`;
290:         } catch {
291:           // ignore parse error
292:         }
293:       }
294:     }
295:   }
296: 
297:   return md;
298: }
