300: function formatAsText(data: any): string {
301:   const { session, messages } = data;
302:   let text = `${i18n.t('session.title')}: ${session.title || i18n.t('session.untitled')}\n`;
303:   text += `${i18n.t('session.id')}: ${session.id}\n`;
304:   text += `${i18n.t('session.createdAt')}: ${new Date(session.time_created * 1000).toLocaleString()}\n`;
305:   text += `${i18n.t('session.messageCount')}: ${session.message_count || messages.length}\n`;
306:   text += `${'='.repeat(50)}\n\n`;
307: 
308:   for (const msg of messages) {
309:     const role = msg.data?.role === 'user' ? 'USER' : 'ASSISTANT';
310:     text += `[${role}]\n`;
311: 
312:     for (const part of msg.parts) {
313:       if (part.type === 'text') {
314:         try {
315:           const textData = JSON.parse(part.data);
316:           text += `${textData.text}\n`;
317:         } catch {
318:           text += `${part.data}\n`;
319:         }
320:       }
321:     }
322:     text += '\n';
323:   }
324: 
325:   return text;
326: }
