async function selectSession(): Promise<void> {
  if (!db.connect()) {
    console.error(i18n.t('errors.databaseConnectionFailed'));
    process.exit(1);
  }

  try {
    const sessions = db.getSessionsWithPreview(50);

    if (sessions.length === 0) {
      console.log(i18n.t('prompts.noSessionsFound'));
      return;
    }

    const { selectedId } = await inquirer.prompt([
      {
        type: 'list',
        name: 'selectedId',
        message: i18n.t('prompts.selectSession'),
        choices: sessions.map(s => ({
          name: `${s.title} (${s.messageCount} ${i18n.t('session.messageCount').toLowerCase()}, ${formatDate(s.updatedAt)})`,
          value: s.id,
        })),
      },
    ]);

    const { confirm } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'confirm',
        message: i18n.t('prompts.confirmResume'),
        default: true,
      },
    ]);

    if (confirm) {
      await launchSession(selectedId);
    }
  } finally {
    db.disconnect();
  }
}

async function searchSessions(): Promise<void> {
  if (!db.connect()) {
    console.error(i18n.t('errors.databaseConnectionFailed'));
    process.exit(1);
  }

  try {
    const { query } = await inquirer.prompt([
      {
        type: 'input',
        name: 'query',
        message: i18n.t('prompts.searchQuery'),
      },
    ]);

    const results = db.searchSessionsWithRelevance(query);

    if (results.length === 0) {
      console.log(i18n.t('prompts.noResultsFound'));
      return;
    }

    console.log(`\n${i18n.getLanguage() === 'zh' ? '找到' : 'Found'} ${results.length} ${i18n.getLanguage() === 'zh' ? '个结果' : 'results'}:\n`);
    results.forEach((s, i) => {
      console.log(`[${i + 1}] ${s.title || i18n.t('session.untitled')} (${formatDate(new Date(s.time_updated * 1000))}) ID: ${s.id}`);
    });

    const { selectedId } = await inquirer.prompt([
      {
        type: 'list',
        name: 'selectedId',
        message: i18n.t('prompts.selectSession'),
        choices: results.map(s => ({
          name: `${s.title || i18n.t('session.untitled')} (${formatDate(new Date(s.time_updated * 1000))})`,
          value: s.id,
        })),
      },
    ]);

    await launchSession(selectedId);
  } finally {
    db.disconnect();
  }
}

