    case 'export':
      if (!args[1]) {
        console.error(i18n.t('errors.invalidSessionId'));
        process.exit(1);
      }
      await exportSession(args[1]);
      break;

    case 'backup':
      await backupSessions({
        includeAll: args.includes('--all'),
        sessionIds: args.slice(1).filter(a => !a.startsWith('--')),
      });
      break;

    case 'lang':
    case 'language':
      await selectLanguage();
      break;

    case 'help':
    case '--help':
    case '-h':
      console.log(`
